fn invalid(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,text)}
fn construction(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn action(cx:&mut StepContext<'_>,d:RetirementDemand,run:impl FnOnce(RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>)->Result<bool,OriginalTurnFailure>{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let mut output=None;admit_original_construction(cx,&mut output,construction(d),|_|Ok(((),run(grant)?)))}
fn fixed(bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes:bytes,depth:1,..Default::default()}}
fn text(target:&mut Option<String>,source:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if target.as_ref().is_some_and(|text|text.len()==source.len()){return Ok(true)}let d=if target.is_none(){RetirementDemand{capacity_bytes:source.len(),..fixed(128)}}else{fixed(192)};action(cx,d,|_|{if target.is_none(){let mut value=String::new();value.try_reserve_exact(source.len()).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original branch text reservation failed"))?;*target=Some(value);}else{let value=target.as_mut().unwrap();let start=value.len();let mut end=(start+64).min(source.len());while !source.is_char_boundary(end){end-=1;}value.push_str(&source[start..end]);}Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})})?;Ok(target.as_ref().is_some_and(|text|text.len()==source.len()))}
fn identifier(target:&mut Option<String>,prefix:&str,digest:[u8;32],cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if target.is_some(){return Ok(true)}let length=prefix.len()+17;let d=RetirementDemand{copy_bytes:128+length,capacity_bytes:length,depth:1,..Default::default()};action(cx,d,|_|{let mut value=String::new();value.try_reserve_exact(length).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original branch identifier reservation failed"))?;value.push_str(prefix);value.push('-');const HEX:&[u8;16]=b"0123456789abcdef";for byte in &digest[..8]{value.push(HEX[(byte>>4)as usize]as char);value.push(HEX[(byte&15)as usize]as char);}*target=Some(value);Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:length,..Default::default()})})?;Ok(target.is_some())}
/// 🏛️ Canonical graph facts and the final authored clock move into one enclosing atomic publication.
pub struct OriginalHistoryBranchMetadataOutput{pub facts:OriginalBranchFacts,pub checkpoint_id:String,pub alternative_id:String,pub clock:HybridLogicalTimestamp,pub commit_clock:Option<HybridLogicalTimestamp>}
semio_framework_value::artifact_retire_struct!(OriginalHistoryBranchMetadataOutput{facts,checkpoint_id,alternative_id,clock,commit_clock});
/// 🧳️ The actual parent publisher pays this fixed source frame before any nested canonical owner is born.
pub struct OriginalHistoryBranchMetadata{binding:Option<OriginalSourceBinding>,decoder:(u64,u64),store:usize,generation:u64,revision:[u8;32],name:(usize,usize),pending:OriginalPendingEditIds,pending_ids:ManuallyDrop<Option<Vec<String>>>,change:OriginalHistoryIdentity,alternative:OriginalHistoryIdentity,checkpoint:OriginalPendingCheckpointIdentity,facts:OriginalBranchFactBirth,prepared:ManuallyDrop<Option<OriginalBranchFacts>>,change_id:ManuallyDrop<Option<String>>,checkpoint_id:ManuallyDrop<Option<String>>,alternative_id:ManuallyDrop<Option<String>>,time:ManuallyDrop<Option<String>>,retirement:RetainedCloneClose,parent:Option<ArtifactHistoryKey>,search:Option<ArtifactHistoryKey>,parent_offset:usize,alternative_search:Option<ArtifactHistoryKey>,alternative_offset:usize,clock:HybridLogicalTimestamp,commit_clock:Option<HybridLogicalTimestamp>,time_bytes:[u8;20],time_start:usize,create:bool,phase:u8,closing:bool}
impl OriginalHistoryBranchMetadata{
 fn empty(binding:OriginalSourceBinding,decoder:(u64,u64),store:usize,generation:u64,revision:[u8;32],name:(usize,usize),clock:HybridLogicalTimestamp)->Self{Self{binding:Some(binding),decoder,store,generation,revision,name,pending:Default::default(),pending_ids:ManuallyDrop::new(None),change:Default::default(),alternative:Default::default(),checkpoint:Default::default(),facts:Default::default(),prepared:ManuallyDrop::new(None),change_id:ManuallyDrop::new(None),checkpoint_id:ManuallyDrop::new(None),alternative_id:ManuallyDrop::new(None),time:ManuallyDrop::new(None),retirement:Default::default(),parent:None,search:None,parent_offset:0,alternative_search:None,alternative_offset:0,clock,commit_clock:None,time_bytes:[0;20],time_start:20,create:false,phase:0,closing:false}}
 /// 📏️ The actual fixed source allocation is priced separately from every bounded body event.
 pub fn birth_demands()->RetirementDemand{RetirementDemand{copy_bytes:2*size_of::<Self>()+size_of::<Box<Self>>(),capacity_bytes:size_of::<Self>(),depth:1,..Default::default()}}
 /// 🎟️ Captures only the actual Store address, generation, revision, caller and original name loan.
 pub fn admit<P,M>(store:&ArtifactStore<P,M>,name:&str,cx:&mut StepContext<'_>,output:&mut Option<Box<Self>>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+Mutation<P>+OpBinary+OpText+Send+'static{let decoder=cx.native_receiving_identity().ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"branch metadata requires its original native decoder recipient"))?;let binding=OriginalSourceBinding::borrow(cx);let d=Self::birth_demands();admit_original_construction(cx,output,construction(d),|_|Ok((Box::new(Self::empty(binding,decoder,store as*const _ as usize,store.generation(),store.content_revision(),(name.as_ptr()as usize,name.len()),store.parts_ref().log.clock)),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})))}
 /// 🌱️ Plans against original Store roots without publishing a graph row or borrowing a cold mutation codec.
 pub fn advance<P,M>(&mut self,store:&ArtifactStore<P,M>,name:&str,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P:ToValue+Send+Sync+'static,M:ToValue+FromValue+Mutation<P>+OpBinary+OpText+Send+'static{
  if self.closing||cx.native_receiving_identity()!=Some(self.decoder)||!self.binding.is_some_and(|binding|binding.matches(cx))||self.store!=store as*const _ as usize||self.generation!=store.generation()||self.revision!=store.content_revision()||self.name!=(name.as_ptr()as usize,name.len()){return Err(invalid("branch metadata changed its original caller, Store, revision or name").into())}if self.ready(){return Ok(true)}let parts=store.parts_ref();let log=parts.log;let parent=match self.parent{Some(key)=>Some(log.envelope.vcs.checkpoints.get_key(key).ok_or_else(||invalid("branch parent checkpoint changed"))?),None=>None};
  match self.phase{
   0=>{let d=self.pending.demands(&log.applied_edit_ids)?;if action(cx,d,|grant|self.pending.advance(self.generation,&log.applied_edit_ids,&log.envelope.vcs.changes,grant,|_|Ok(())))?&&self.pending.ready(){self.phase=1;}},
   1=>{let d=fixed(size_of::<Vec<String>>()+128);if action(cx,d,|grant|{let Some((ids,p))=self.pending.take(grant)?else{return Ok(Default::default())};*self.pending_ids=Some(ids);Ok(p)})?{self.phase=2;}},
   2=>{if action(cx,fixed(256),|_|{self.create=!self.pending_ids.as_ref().unwrap().is_empty()||log.envelope.vcs.checkpoints.is_empty();if self.create&&self.pending_ids.as_ref().unwrap().is_empty(){return Err(invalid("branch checkpoint requires an original uncommitted edit"))}self.search=log.envelope.vcs.checkpoints.last_key();self.parent=if log.current_checkpoint_id.is_none()&&!self.create{self.search}else{None};let now=semio_framework_os_store_initialization_runtime::lifted_document_materialize::now_ms();let mut value=now;self.time_start=self.time_bytes.len();loop{self.time_start-=1;self.time_bytes[self.time_start]=b'0'+(value%10)as u8;value/=10;if value==0{break}}self.clock.tick(now);if self.create{self.commit_clock=Some(self.clock);self.clock.tick(now);}self.phase=if log.current_checkpoint_id.is_some(){3}else{4};Ok(RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()})})?{}},
   3=>{action(cx,fixed(256),|_|{let key=self.search.ok_or_else(||invalid("branch source current checkpoint has no original row"))?;let checkpoint=log.envelope.vcs.checkpoints.get_key(key).ok_or_else(||invalid("branch checkpoint lookup changed"))?;let current=log.current_checkpoint_id.as_deref().ok_or_else(||invalid("branch source current checkpoint disappeared"))?;let end=(self.parent_offset+64).min(current.len());if checkpoint.id.len()!=current.len()||checkpoint.id.as_bytes()[self.parent_offset..end]!=current.as_bytes()[self.parent_offset..end]{self.search=log.envelope.vcs.checkpoints.previous_key(key);self.parent_offset=0;}else if end==current.len(){self.parent=Some(key);self.parent_offset=0;self.phase=4;}else{self.parent_offset=end;}Ok(RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()})})?;},
   4=>{let original=std::str::from_utf8(&self.time_bytes[self.time_start..]).map_err(|_|invalid("branch clock lost decimal identity"))?;if text(&mut self.time,original,cx)?{self.phase=if self.create{5}else{9};}},
   5=>{let input=OriginalHistoryIdentityInput::Change{edit_ids:self.pending_ids.as_ref().unwrap(),description:None};let d=self.change.demands();if action(cx,d,|grant|self.change.advance(self.generation,&input,grant))?&&self.change.digest().is_some(){self.phase=6;}},
   6=>{if identifier(&mut self.change_id,"change",self.change.digest().unwrap(),cx)?{self.phase=7;}},
   7=>{let input=OriginalPendingCheckpointInput{generation:self.generation,parent:parent.map(|p|p.id.as_str()),prior_change_ids:parent.map_or(&[],|p|p.change_ids.as_slice()),changes:&log.envelope.vcs.changes,pending_id:self.change_id.as_deref().unwrap(),pending_edits:self.pending_ids.as_ref().unwrap(),pending_description:None,saved_at:self.time.as_deref().unwrap(),timestamp:self.time.as_deref().unwrap(),message:None,authors:&[]};let d=self.checkpoint.demands();if action(cx,d,|grant|self.checkpoint.advance(&input,grant))?&&self.checkpoint.digest().is_some(){self.phase=8;}},
   8=>{if identifier(&mut self.checkpoint_id,"ck",self.checkpoint.digest().unwrap(),cx)?{self.phase=10;}},
   9=>{let id=parent.ok_or_else(||invalid("branch source has no checkpoint"))?.id.as_str();if text(&mut self.checkpoint_id,id,cx)?{self.phase=10;}},
   10=>{let input=OriginalHistoryIdentityInput::Alternative{name,checkpoint_id:self.checkpoint_id.as_deref().unwrap()};let d=self.alternative.demands();if action(cx,d,|grant|self.alternative.advance(self.generation,&input,grant))?&&self.alternative.digest().is_some(){self.phase=11;}},
   11=>{if identifier(&mut self.alternative_id,"alternative",self.alternative.digest().unwrap(),cx)?{self.alternative_search=log.envelope.vcs.alternatives.last_key();self.phase=18;}},
   18=>{action(cx,fixed(256),|_|{if let Some(key)=self.alternative_search{let alternative=log.envelope.vcs.alternatives.get_key(key).ok_or_else(||invalid("branch alternative lookup changed"))?;let original=self.alternative_id.as_deref().unwrap();let end=(self.alternative_offset+64).min(original.len());if alternative.id.len()!=original.len()||alternative.id.as_bytes()[self.alternative_offset..end]!=original.as_bytes()[self.alternative_offset..end]{self.alternative_search=log.envelope.vcs.alternatives.previous_key(key);self.alternative_offset=0;}else if end==original.len(){return Err(ValueError::literal(ValueRefusalKind::InvalidValue,"branch alternative already exists"))}else{self.alternative_offset=end;}}else{self.phase=12;}Ok(RetainedCloneProgress{copied_items:1,copied_bytes:256,..Default::default()})})?;},
   12=>{let input=OriginalBranchFactInput{generation:self.generation,parent,change_id:self.change_id.as_deref().unwrap_or(""),checkpoint_id:self.checkpoint_id.as_deref().unwrap(),alternative_id:self.alternative_id.as_deref().unwrap(),name,saved_at:self.time.as_deref().unwrap(),timestamp:self.time.as_deref().unwrap(),create_checkpoint:self.create};let d=self.facts.demands(&input)?;if action(cx,d,|grant|self.facts.advance(&input,&mut self.pending_ids,grant,|_|Ok(())))?&&self.facts.ready(){self.phase=13;}},
   13=>{let d=fixed(size_of::<OriginalBranchFacts>()+128);if action(cx,d,|grant|{let Some((facts,p))=self.facts.take(grant)?else{return Ok(Default::default())};*self.prepared=Some(facts);Ok(p)})?{self.phase=14;}},
   14=>{if !self.change.terminal_is_empty(){action(cx,fixed(128),|grant|Ok(self.change.close_step(grant)))?;}else if !self.alternative.terminal_is_empty(){action(cx,fixed(128),|grant|Ok(self.alternative.close_step(grant)))?;}else if !self.checkpoint.terminal_is_empty(){action(cx,fixed(size_of::<Option<(u64,[usize;22])>>()+size_of::<Option<[u8;32]>>()),|grant|Ok(self.checkpoint.close_step(grant)))?;}else{self.phase=15;}},
   15=>{if !self.retirement.is_empty(){self.retire_active(cx)?;}else if self.change_id.is_some(){self.retire_text(0,cx)?;}else if self.time.is_some(){self.retire_text(3,cx)?;}else{self.phase=16;}},
   _=>return Err(invalid("branch metadata phase changed").into()),
  }Ok(self.ready())
 }
 /// 🏁️ Complete canonical metadata remains private until the enclosing original publication takes it.
 pub fn ready(&self)->bool{self.phase==16&&!self.closing}
 pub fn prepared(&self)->Option<&OriginalBranchFacts>{self.ready().then(||self.prepared.as_ref().unwrap())}
 /// 🤝️ Transfers the same canonical rows and exact admitted identity allocations.
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<OriginalHistoryBranchMetadataOutput>)->Result<bool,OriginalTurnFailure>{if cx.native_receiving_identity()!=Some(self.decoder)||!self.binding.is_some_and(|binding|binding.matches(cx))||!self.ready(){return Err(invalid("branch metadata handoff changed its original source").into())}let d=fixed(size_of::<OriginalHistoryBranchMetadataOutput>()+128);let result=admit_original_construction(cx,output,construction(d),|_|{let value=OriginalHistoryBranchMetadataOutput{facts:self.prepared.take().unwrap(),checkpoint_id:self.checkpoint_id.take().unwrap(),alternative_id:self.alternative_id.take().unwrap(),clock:self.clock,commit_clock:self.commit_clock};self.phase=17;Ok((value,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))})?;Ok(result)}
 fn retire_active(&mut self,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let selection=self.retirement.select(cx.retained_grant().maximum_copy_bytes)?;let d=selection.demands();close_original_retained_step(cx,d,|grant|selection.step(grant))?;Ok(())}
 fn retirement_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{self.retirement.demands(body)}
 fn retire_text(&mut self,index:u8,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let d=self.retirement.next_owner_demands::<String>(true,&None,cx.retained_grant().maximum_copy_bytes)?;let target=match index{0=>&mut self.change_id,1=>&mut self.checkpoint_id,2=>&mut self.alternative_id,_=>&mut self.time};close_original_retained_step(cx,d,|grant|Ok(self.retirement.begin_granted(target,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;Ok(())}
 /// 📏️ The next genuine child or canonical owner supplies the exact enclosing close quote.
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.retirement.is_empty(){return self.retirement_demands(body)}if !self.pending.terminal_is_empty(){return self.pending.close_demands(body)}if !self.facts.terminal_is_empty(){return self.facts.close_demands(body)}if !self.change.terminal_is_empty()||!self.alternative.terminal_is_empty(){return Ok(fixed(128))}if !self.checkpoint.terminal_is_empty(){return Ok(fixed(size_of::<Option<(u64,[usize;22])>>()+size_of::<Option<[u8;32]>>()))}if self.prepared.is_some(){return self.retirement.next_owner_demands::<OriginalBranchFacts>(true,&None,body)}if self.pending_ids.is_some(){return self.retirement.next_owner_demands::<Vec<String>>(true,&None,body)}if self.change_id.is_some()||self.checkpoint_id.is_some()||self.alternative_id.is_some()||self.time.is_some(){return self.retirement.next_owner_demands::<String>(true,&None,body)}Ok(fixed(128))}
 /// 🛑️ Cancellation follows the original source fence and closes every partly authored canonical owner.
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if cx.native_receiving_identity()!=Some(self.decoder)||!self.binding.is_some_and(|binding|binding.matches(cx)){return Err(invalid("branch closure changed its original caller").into())}self.closing=true;if !self.retirement.is_empty(){self.retire_active(cx)?;}else if !self.pending.terminal_is_empty(){let d=self.pending.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|self.pending.close_step(grant))?;}else if !self.facts.terminal_is_empty(){let d=self.facts.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|self.facts.close_step(grant))?;}else if !self.change.terminal_is_empty(){close_original_retained_step(cx,fixed(128),|grant|Ok(RetainedCloneStep::Progress(self.change.close_step(grant))))?;}else if !self.alternative.terminal_is_empty(){close_original_retained_step(cx,fixed(128),|grant|Ok(RetainedCloneStep::Progress(self.alternative.close_step(grant))))?;}else if !self.checkpoint.terminal_is_empty(){let d=fixed(size_of::<Option<(u64,[usize;22])>>()+size_of::<Option<[u8;32]>>());close_original_retained_step(cx,d,|grant|Ok(RetainedCloneStep::Progress(self.checkpoint.close_step(grant))))?;}else if self.prepared.is_some(){let d=self.retirement.next_owner_demands::<OriginalBranchFacts>(true,&None,cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|Ok(self.retirement.begin_granted(&mut self.prepared,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;}else if self.pending_ids.is_some(){let d=self.retirement.next_owner_demands::<Vec<String>>(true,&None,cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|grant|Ok(self.retirement.begin_granted(&mut self.pending_ids,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default()))))?;}else if self.change_id.is_some(){self.retire_text(0,cx)?;}else if self.checkpoint_id.is_some(){self.retire_text(1,cx)?;}else if self.alternative_id.is_some(){self.retire_text(2,cx)?;}else if self.time.is_some(){self.retire_text(3,cx)?;}else{let d=fixed(128);close_original_retained_step(cx,d,|_|{self.binding=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:128,..Default::default()}))})?;}Ok(self.terminal_is_empty())}
 pub fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.pending.terminal_is_empty()&&self.facts.terminal_is_empty()&&self.change.terminal_is_empty()&&self.alternative.terminal_is_empty()&&self.checkpoint.terminal_is_empty()&&self.pending_ids.is_none()&&self.prepared.is_none()&&self.change_id.is_none()&&self.checkpoint_id.is_none()&&self.alternative_id.is_none()&&self.time.is_none()&&self.retirement.is_empty()}
}
impl Drop for OriginalHistoryBranchMetadata{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"branch metadata requires complete original source closure");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.pending_ids);ManuallyDrop::drop(&mut self.prepared);ManuallyDrop::drop(&mut self.change_id);ManuallyDrop::drop(&mut self.checkpoint_id);ManuallyDrop::drop(&mut self.alternative_id);ManuallyDrop::drop(&mut self.time);}}}}

